import { define, effecting } from '@gost-kit/common';
import type { ApiError, AppAction, AppEffect, Dependencies } from './contracts.js';

// Pre-existing test-only application boundary. Feature implementation must reuse
// this file unchanged; transport/normalization policy is not generated by a skill.
export const createAppEffector = (dependencies: Dependencies, alerts: string[]) => {
  const appHandlers = define.effector<AppAction, AppEffect>({
    AlertEffect: async ({ effect }) => { alerts.push(effect.message); },
    ApiEffect: async ({ effect, dispatch }) => {
      let rows;
      try { rows = await dependencies.loadStaff(); }
      catch (error) {
        const errors: ApiError[] = [{
          code: 'OFFLINE', message: error instanceof Error ? error.message : String(error), path: [],
        }];
        await dispatch(effect.receiverError(errors));
        return;
      }
      await dispatch(effect.receiverSuccess(rows));
    },
  });
  return effecting<AppAction, AppEffect, [typeof appHandlers]>(appHandlers);
};
